import { useState, FormEvent } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxButton,
} from '@jinx-ui/react';

interface RegistrationFormProps {
  onSubmit: (data: {
    fullName: string;
    email: string;
    phone: string;
    address: string;
    city: string;
    postalCode: string;
  }) => void;
}

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [address, setAddress] = useState('');
  const [city, setCity] = useState('');
  const [postalCode, setPostalCode] = useState('');

  const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];
  const lastStep = steps.length - 1;

  const goBack = () => setStep((current) => Math.max(current - 1, 0));
  const goNext = () => setStep((current) => Math.min(current + 1, lastStep));

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (step < lastStep) {
      goNext();
      return;
    }
    onSubmit({ fullName, email, phone, address, city, postalCode });
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        maxWidth: '420px',
        padding: '24px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
      }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Полное имя"
            required
            value={fullName}
            onChange={(event) => setFullName(event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={email}
            onChange={(event) => setEmail(event.target.value)}
          />
          <JxInputField
            label="Телефон"
            prefix="+7"
            value={phone}
            onChange={(event) => setPhone(event.target.value)}
          />
        </div>
      ) : null}

      {step === 1 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxTextareaField
            label="Адрес"
            rows={3}
            required
            value={address}
            onChange={(event) => setAddress(event.target.value)}
          />
          <JxInputField
            label="Город"
            required
            value={city}
            onChange={(event) => setCity(event.target.value)}
          />
          <JxInputField
            label="Почтовый индекс"
            value={postalCode}
            onChange={(event) => setPostalCode(event.target.value)}
          />
        </div>
      ) : null}

      {step === 2 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <p style={{ color: 'var(--jx-text-2)', fontSize: '14px', margin: 0 }}>
            Проверьте данные перед отправкой.
          </p>
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              gap: '4px',
              padding: '12px',
              background: 'var(--jx-surface-2)',
              borderRadius: 'var(--jx-r)',
            }}
          >
            <span>
              <strong style={{ color: 'var(--jx-text)' }}>Имя:</strong>{' '}
              <span style={{ color: 'var(--jx-text-2)' }}>{fullName || '—'}</span>
            </span>
            <span>
              <strong style={{ color: 'var(--jx-text)' }}>Почта:</strong>{' '}
              <span style={{ color: 'var(--jx-text-2)' }}>{email || '—'}</span>
            </span>
            <span>
              <strong style={{ color: 'var(--jx-text)' }}>Телефон:</strong>{' '}
              <span style={{ color: 'var(--jx-text-2)' }}>{phone || '—'}</span>
            </span>
            <span>
              <strong style={{ color: 'var(--jx-text)' }}>Адрес:</strong>{' '}
              <span style={{ color: 'var(--jx-text-2)' }}>{address || '—'}</span>
            </span>
            <span>
              <strong style={{ color: 'var(--jx-text)' }}>Город:</strong>{' '}
              <span style={{ color: 'var(--jx-text-2)' }}>{city || '—'}</span>
            </span>
            <span>
              <strong style={{ color: 'var(--jx-text)' }}>Индекс:</strong>{' '}
              <span style={{ color: 'var(--jx-text-2)' }}>{postalCode || '—'}</span>
            </span>
          </div>
        </div>
      ) : null}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < lastStep ? (
          <JxButton variant="primary" type="submit">
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" type="submit">
            Отправить
          </JxButton>
        )}
      </div>
    </form>
  );
}

